INSERT INTO state_legal_sources (jurisdiction_id,title,source_type,issuing_authority,source_url,verification_status,reliability_score,notes) SELECT id,'Ekiti State Laws and Regulations','Official legal repository','Ekiti State Government','https://www.ekitistate.gov.ng/laws-and-regulations','Verified',99,'Repository lists the Ekiti State Urban and Regional Planning and Development Law, Land Use Act and other state instruments.' FROM state_legal_jurisdictions WHERE state_code='EK' AND lga_code IS NULL AND NOT EXISTS (SELECT 1 FROM state_legal_sources s WHERE s.title='Ekiti State Laws and Regulations');
INSERT INTO state_legal_sources (jurisdiction_id,title,source_type,issuing_authority,source_url,verification_status,reliability_score,notes) SELECT id,'Ministry of Housing and Urban Development functions and planning permits','Official government agency page','Ekiti State Ministry of Housing and Urban Development','https://www.ekitistate.gov.ng/executive-council/mdas/ministry-of-housing-and-urban-development','Verified',98,'Describes planning permits, layouts, land-use plans, development control and land-use clearance functions.' FROM state_legal_jurisdictions WHERE state_code='EK' AND lga_code IS NULL AND NOT EXISTS (SELECT 1 FROM state_legal_sources s WHERE s.title='Ministry of Housing and Urban Development functions and planning permits');
INSERT INTO state_legal_sources (jurisdiction_id,title,source_type,issuing_authority,source_url,verification_status,reliability_score,notes) SELECT id,'Ekiti State Building Regulations 2017','Official regulation','Ekiti State Government','https://www.ekitistate.gov.ng/wp-content/uploads/saber/Ekiti%20State%20Building%20Regulation%2C%202017.%28E%29.pdf','Verified',97,'Provides layout approval and land-use clearance triggers for specified developments.' FROM state_legal_jurisdictions WHERE state_code='EK' AND lga_code IS NULL AND NOT EXISTS (SELECT 1 FROM state_legal_sources s WHERE s.title='Ekiti State Building Regulations 2017');
INSERT INTO state_legal_sources (jurisdiction_id,title,source_type,issuing_authority,source_url,verification_status,reliability_score,notes) SELECT id,'CoFO Processing Approved Fees Order','Official procedure/fee schedule','Ekiti State Bureau of Land Services','https://www.ekitistate.gov.ng/wp-content/uploads/saber/CoOProcedure.pdf','Verified',96,'Shows published requirements and fee schedule examples for Certificates of Occupancy by location and land use.' FROM state_legal_jurisdictions WHERE state_code='EK' AND lga_code IS NULL AND NOT EXISTS (SELECT 1 FROM state_legal_sources s WHERE s.title='CoFO Processing Approved Fees Order');
INSERT INTO state_legal_sources (jurisdiction_id,title,source_type,issuing_authority,source_url,verification_status,reliability_score,notes) SELECT id,'FRILIA Land and Agriculture Investment Approval Toolkit','Official investment/governance toolkit','Ekiti State Government / EKDIPA','https://ekitistate.gov.ng/wp-content/uploads/saber/New/FRILLA_LAEAIR_Toolkit.pdf','Verified',95,'Describes large-scale agricultural investment screening, KYC/due diligence and stakeholder engagement workflow.' FROM state_legal_jurisdictions WHERE state_code='EK' AND lga_code IS NULL AND NOT EXISTS (SELECT 1 FROM state_legal_sources s WHERE s.title='FRILIA Land and Agriculture Investment Approval Toolkit');